window.SAT_QUESTIONS={"version":1,"metadata":{"notes":"Original Azaman-authored practice bank. No College Board questions or answer keys.","counts":{"rw1":27,"rw2_easy":27,"rw2_hard":27,"math1":22,"math2_easy":22,"math2_hard":22}},"rw1":[{"id":"RWM1Q1","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"easy","prompt":"Which choice best states the main idea of the text?","options":["The garden served practical and social purposes.","The garden replaced every grocery store in the neighborhood.","Residents preferred the unused lot to the garden.","The garden produced more food than expected."],"answer":"A","explanation":"The text explicitly identifies both food and community benefits.","source":{"title":"Original practice passage","paragraphs":["A community garden added twelve plots to an unused lot. After one season, nearby residents reported that the garden provided fresh produce and also created a place to meet neighbors."]}},{"id":"RWM1Q2","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"easy","prompt":"As used in the text, “unexpected” most nearly means","options":["Unforeseen","Unwelcome","Temporary","Unimportant"],"answer":"A","explanation":"The director did not anticipate the high attendance.","source":{"title":"Original practice passage","paragraphs":["When the museum opened, its director called the small exhibit an “unexpected success,” noting that attendance had exceeded projections."]}},{"id":"RWM1Q3","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","prompt":"The city planted shade trees along several sidewalks. ___, summer surveys found that pedestrians were more likely to walk on those routes.","options":["In contrast","As a result","For example","Meanwhile"],"answer":"B","explanation":"The survey finding is presented as a consequence of planting the trees.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The city planted shade trees along several sidewalks. ___, summer surveys found that pedestrians were more likely to walk on those routes."]}},{"id":"RWM1Q4","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Subject-verb agreement","difficulty":"easy","prompt":"The collection of field notes from the expedition ___ in the university archive.","options":["are stored","were stored","is stored","have been stored"],"answer":"C","explanation":"The singular subject “collection” takes “is.”","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The collection of field notes from the expedition ___ in the university archive."]}},{"id":"RWM1Q5","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"easy","prompt":"How much greater was Group B's average than Group A's?","options":["1.3 hours","1.7 hours","7.7 hours","8.1 hours"],"answer":"A","explanation":"Subtracting 3.2 from 4.5 gives 1.3 hours.","source":{"title":"Original practice passage","paragraphs":["A study compared the average daily screen time of two groups. Group A averaged 3.2 hours; Group B averaged 4.5 hours."]}},{"id":"RWM1Q6","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"easy","prompt":"Why does the author present the study after describing the assumption?","options":["To challenge a belief with evidence","To provide a historical timeline","To introduce a competing species","To summarize the study's methods"],"answer":"A","explanation":"The study is used to complicate the initial assumption.","source":{"title":"Original practice passage","paragraphs":["The author first describes a common assumption about urban bees, then presents a study that complicates that assumption."]}},{"id":"RWM1Q7","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"easy","prompt":"The researchers tested three materials ___ cork, bamboo, and recycled foam.","options":["materials, cork","materials: cork","materials; cork","materials cork"],"answer":"B","explanation":"A colon properly introduces a list after a complete clause.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The researchers tested three materials ___ cork, bamboo, and recycled foam."]}},{"id":"RWM1Q8","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"easy","prompt":"Which choice most effectively uses the notes to introduce the program?","options":["The library offers free Saturday coding workshops for teens.","The library is one of several buildings downtown.","Many coding programs meet during the week.","Teens often visit libraries for many reasons."],"answer":"A","explanation":"It includes all three relevant notes directly.","source":{"title":"Original practice passage","paragraphs":["A student has notes about a local library program: it offers free coding workshops, meets every Saturday, and is open to teens."]}},{"id":"RWM1Q9","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"medium","prompt":"What can reasonably be inferred?","options":["The revised procedure improved consistency.","The first trial proved the hypothesis false.","The researchers abandoned the experiment.","The second trial used fewer measurements."],"answer":"A","explanation":"The text connects the procedural revision with more consistent results.","source":{"title":"Original practice passage","paragraphs":["Although the first trial produced uneven results, the researchers revised the measurement procedure before repeating the experiment. The second trial produced much more consistent data."]}},{"id":"RWM1Q10","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"medium","prompt":"How would the authors most likely respond to each other?","options":["They would disagree about the primary benefit of rooftop farms.","They would both reject rooftop farming.","They would agree that transportation is irrelevant.","They would agree that education is the only benefit."],"answer":"A","explanation":"The texts emphasize different primary benefits.","source":{"title":"Original practice passage","paragraphs":["Text 1 argues that rooftop farms can reduce the distance food travels. Text 2 argues that rooftop farms are valuable mainly because they create educational spaces."]}},{"id":"RWM1Q11","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Verb tense","difficulty":"medium","prompt":"By the time the committee met in June, the volunteers ___ the survey responses for three weeks.","options":["review","have reviewed","had reviewed","will review"],"answer":"C","explanation":"Past perfect shows an action completed before another past event.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: By the time the committee met in June, the volunteers ___ the survey responses for three weeks."]}},{"id":"RWM1Q12","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","prompt":"The first prototype was inexpensive to build. ___, it used a material that could not withstand heat.","options":["Therefore","However","For instance","Similarly"],"answer":"B","explanation":"The second sentence contrasts with the first.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The first prototype was inexpensive to build. ___, it used a material that could not withstand heat."]}},{"id":"RWM1Q13","section":"Reading and Writing","domain":"Information and Ideas","skill":"Command of evidence","difficulty":"medium","prompt":"Which finding best supports the claim that the restoration benefited bird habitat?","options":["Nesting species increased from 18 to 27.","The project lasted two years.","The wetland covered 40 acres.","Workers planted native grasses."],"answer":"A","explanation":"The increase in nesting species is direct evidence of improved habitat.","source":{"title":"Original practice passage","paragraphs":["A report notes that a wetland restoration project increased the number of nesting birds from 18 species to 27 species in two years."]}},{"id":"RWM1Q14","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"medium","prompt":"As used in the text, “restrained” most nearly means","options":["Measured","Confused","Enthusiastic","Incomplete"],"answer":"A","explanation":"The account avoids exaggerated praise and stays measured.","source":{"title":"Original practice passage","paragraphs":["The historian's account is notably restrained: rather than praising the leader, it lists the policy's measurable effects."]}},{"id":"RWM1Q15","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Sentence boundaries","difficulty":"medium","prompt":"The telescope was difficult to transport ___ once assembled, it produced unusually clear images.","options":["transport, once","transport; once","transport once","transport: once"],"answer":"B","explanation":"A semicolon properly separates the two independent clauses.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The telescope was difficult to transport ___ once assembled, it produced unusually clear images."]}},{"id":"RWM1Q16","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"medium","prompt":"Which choice best states the main idea?","options":["The trees' growth pattern changed as their roots developed.","The trees stopped growing after three years.","Deep soil always causes rapid growth.","Researchers studied only mature trees."],"answer":"A","explanation":"The text emphasizes a change linked to root development.","source":{"title":"Original practice passage","paragraphs":["Researchers found that the tree species grew slowly during the first three years but then showed sharply increased growth after their roots reached deeper soil."]}},{"id":"RWM1Q17","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"medium","prompt":"Which choice best introduces the piece using the notes?","options":["The 2024 piece draws on bird recordings and birdlike rhythms.","The composer has written many orchestral works.","Bird recordings can be difficult to collect.","The premiere attracted several musicians."],"answer":"A","explanation":"The sentence combines the most relevant notes.","source":{"title":"Original practice passage","paragraphs":["A student has notes: a composer studied field recordings of birds; she incorporated birdlike rhythms into a new orchestral piece; the piece premiered in 2024."]}},{"id":"RWM1Q18","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"medium","prompt":"What is the primary function of the middle portion?","options":["To contrast two approaches to reporting","To list the movement's founders","To define a technical term","To evaluate a single article"],"answer":"A","explanation":"The middle section establishes the contrast.","source":{"title":"Original practice passage","paragraphs":["The passage opens with a definition of “slow journalism,” then contrasts it with rapid online reporting before describing the movement's goals."]}},{"id":"RWM1Q19","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Pronoun agreement","difficulty":"medium","prompt":"Each of the interns submitted ___ report before leaving for the day.","options":["their","they're","them","its"],"answer":"A","explanation":"Singular “they” agrees with “each” without changing the meaning.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: Each of the interns submitted ___ report before leaving for the day."]}},{"id":"RWM1Q20","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"medium","prompt":"Which month had the second-highest rainfall?","options":["January","February","March","April"],"answer":"C","explanation":"The values rank February first and March second.","source":{"title":"Original practice passage","paragraphs":["A chart shows monthly rainfall of 42 mm, 58 mm, 51 mm, and 49 mm from January through April."]}},{"id":"RWM1Q21","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “provisional” most nearly means","options":["Tentative","Secretive","Permanent","Controversial"],"answer":"A","explanation":"The policy is presented as temporary or subject to revision.","source":{"title":"Original practice passage","paragraphs":["The author calls the policy “provisional,” emphasizing that officials expect to revise it after collecting more data."]}},{"id":"RWM1Q22","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"hard","prompt":"Which inference is best supported?","options":["Reminders may be especially useful for borrowers with a history of late returns.","Reminders eliminate all late returns.","Participants disliked the reminders.","Only frequent borrowers responded."],"answer":"A","explanation":"The largest effect occurred in the previously late-returning group.","source":{"title":"Original practice passage","paragraphs":["A survey found that participants who received brief reminders were slightly more likely to return library books on time. The difference was greatest among participants who had previously returned books late."]}},{"id":"RWM1Q23","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The two batteries were similar in size and weight. ___, one stored nearly twice as much energy as the other.","options":["Nevertheless","Likewise","For example","In addition"],"answer":"A","explanation":"The sentence highlights a surprising contrast.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The two batteries were similar in size and weight. ___, one stored nearly twice as much energy as the other."]}},{"id":"RWM1Q24","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"hard","prompt":"The survey included one open-ended question ___ participants could explain their reasoning in their own words.","options":["question, in which","question; in which","question in which","question: in which"],"answer":"C","explanation":"No punctuation is needed before the restrictive relative clause.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The survey included one open-ended question ___ participants could explain their reasoning in their own words."]}},{"id":"RWM1Q25","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","prompt":"Which choice best describes the relationship between the texts?","options":["Text 2 adds a potential drawback to Text 1's positive view.","Text 2 rejects the existence of public murals.","Text 1 focuses only on economic effects.","The texts make identical claims about redevelopment."],"answer":"A","explanation":"Text 2 accepts a benefit while adding a complication.","source":{"title":"Original practice passage","paragraphs":["Text 1 argues that public murals can strengthen neighborhood identity. Text 2 agrees but warns that murals can also accelerate redevelopment and displacement."]}},{"id":"RWM1Q26","section":"Reading and Writing","domain":"Information and Ideas","skill":"Command of evidence","difficulty":"hard","prompt":"Which conclusion is best supported by the results?","options":["Moderate shade may balance water retention with growth.","Full sun is always best for plants.","Heavy shade increases growth rate.","Water retention has no relation to light."],"answer":"A","explanation":"The results show a trade-off and a middle condition.","source":{"title":"Original practice passage","paragraphs":["In an experiment, plants exposed to moderate shade retained more water than plants in full sun, while plants in heavy shade grew less quickly."]}},{"id":"RWM1Q27","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice most effectively presents the significance of the bridge?","options":["Its steel-truss design enabled longer spans and influenced later bridge construction.","The bridge was built in 1890 in a growing city.","Engineers used stone before steel became common.","Other cities had bridges of many different designs."],"answer":"A","explanation":"The choice connects the structural innovation with its influence.","source":{"title":"Original practice passage","paragraphs":["Notes: the 1890 bridge used steel trusses; its design allowed a longer span than earlier stone bridges; engineers copied the design in other cities."]}}],
"rw2":{"easy":[],"hard":[{"id":"RWM2HQ1","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “equivocal” most nearly means","options":["ambiguous","exhaustive","predictable","irrelevant"],"answer":"A","explanation":"The ending allows multiple interpretations, so it is ambiguous.","source":{"title":"Original practice passage","paragraphs":["The critic describes the novel's ending as “deliberately equivocal,” because the final scene supports more than one plausible interpretation."]}},{"id":"RWM2HQ2","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"hard","prompt":"Which inference is best supported?","options":["The new schedule may improve water efficiency.","The new schedule always increases yield.","The older schedule requires no irrigation.","The farmers stopped growing crops."],"answer":"A","explanation":"Using less water for a similar yield suggests greater efficiency.","source":{"title":"Original practice passage","paragraphs":["After a drought year, farmers who adopted the new irrigation schedule used less water while maintaining nearly the same crop yield as farmers using the older schedule."]}},{"id":"RWM2HQ3","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The first survey measured attitudes immediately after the workshop. ___, the researchers conducted a second survey six months later to see whether the change lasted.","options":["In addition","By contrast","For instance","As a result"],"answer":"A","explanation":"The second survey is an additional step.","source":{"title":"Original practice passage","paragraphs":["The first survey measured attitudes immediately after the workshop. ___, the researchers conducted a second survey six months later to see whether the change lasted."]}},{"id":"RWM2HQ4","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Agreement","difficulty":"hard","prompt":"Neither the collection of maps nor the field journals ___ available for public viewing yet.","options":["is","are","was","has been"],"answer":"B","explanation":"With “neither...nor,” the verb agrees with the nearer plural subject, “journals.”","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: Neither the collection of maps nor the field journals ___ available for public viewing yet."]}},{"id":"RWM2HQ5","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"hard","prompt":"Which claim is best supported by the graph?","options":["Capacity declines as charge cycles increase.","Capacity rises after 200 cycles.","The battery loses exactly 11% each time.","The battery reaches zero capacity at 400 cycles."],"answer":"A","explanation":"Every later measurement is lower than the previous one.","source":{"title":"Original practice passage","paragraphs":["A graph shows that a battery retained 92%, 81%, 74%, and 68% of its original capacity after 100, 200, 300, and 400 charge cycles."]}},{"id":"RWM2HQ6","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"hard","prompt":"Why does the author evaluate the explanations after presenting them?","options":["To compare their evidentiary strength","To introduce a third migration pattern","To define migration","To summarize unrelated research"],"answer":"A","explanation":"The evaluation helps readers compare the explanations.","source":{"title":"Original practice passage","paragraphs":["The author presents two explanations for a migration pattern and then evaluates the evidence supporting each explanation."]}},{"id":"RWM2HQ7","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"hard","prompt":"The committee's recommendation was concise ___ it nevertheless addressed every major concern raised during the hearing.","options":["concise, but","concise; but","concise but;","concise: but"],"answer":"A","explanation":"A comma and coordinating conjunction join the independent clauses.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The committee's recommendation was concise ___ it nevertheless addressed every major concern raised during the hearing."]}},{"id":"RWM2HQ8","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice best emphasizes the archive's new usefulness to researchers?","options":["Digitized photographs with searchable captions can be located by date and place.","The archive contains many photographs from different years.","Volunteers contributed time to the digitization project.","Researchers sometimes visit archives to study images."],"answer":"A","explanation":"It directly connects digitization and captions to searchable access.","source":{"title":"Original practice passage","paragraphs":["Notes: the archive digitized 12,000 photographs; volunteers added searchable captions; researchers can now locate images by date and place."]}},{"id":"RWM2HQ9","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"hard","prompt":"Which choice best states the central idea?","options":["Results became more realistic when the experiment included relevant environmental factors.","The first phase was more accurate than the second.","Field observations are too complex to study experimentally.","The authors rejected controlled experiments."],"answer":"A","explanation":"The contrast between phases supports this conclusion.","source":{"title":"Original practice passage","paragraphs":["The experiment's first phase isolated one variable, while the second phase introduced several realistic environmental factors. The authors report that the second phase produced results closer to field observations."]}},{"id":"RWM2HQ10","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","prompt":"How does Text 2 qualify Text 1?","options":["It adds an environmental cost to an otherwise positive assessment.","It disputes that buses produce emissions.","It argues that batteries cannot be recycled.","It changes the topic from transportation to agriculture."],"answer":"A","explanation":"Text 2 adds a cost without rejecting the main benefit.","source":{"title":"Original practice passage","paragraphs":["Text 1 argues that electric buses can lower urban emissions. Text 2 agrees but notes that manufacturing batteries also has environmental costs."]}},{"id":"RWM2HQ11","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Verb tense","difficulty":"hard","prompt":"By the time the article appeared in print, the researchers ___ their findings at three conferences.","options":["present","presented","had presented","will present"],"answer":"C","explanation":"Past perfect indicates earlier completed presentations.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: By the time the article appeared in print, the researchers ___ their findings at three conferences."]}},{"id":"RWM2HQ12","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The device can detect very small changes in temperature. ___, it is too fragile for use in the field without protective housing.","options":["Therefore","However","Similarly","For example"],"answer":"B","explanation":"The second sentence limits the practical usefulness of the first.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The device can detect very small changes in temperature. ___, it is too fragile for use in the field without protective housing."]}},{"id":"RWM2HQ13","section":"Reading and Writing","domain":"Information and Ideas","skill":"Command of evidence","difficulty":"hard","prompt":"Which result most directly supports the claim that the new lanes encouraged cycling?","options":["Bicycle traffic rose 41%.","Automobile traffic changed by less than 2%.","Two intersections were studied.","The comparison used before-and-after data."],"answer":"A","explanation":"The large increase in bicycle traffic is direct evidence.","source":{"title":"Original practice passage","paragraphs":["A city compared two intersections before and after adding protected bike lanes. Bicycle traffic rose 41%, while automobile traffic changed by less than 2%."]}},{"id":"RWM2HQ14","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “cautious” most nearly means","options":["careful","dismissive","celebratory","impatient"],"answer":"A","explanation":"The author avoids a strong conclusion and stresses further evidence.","source":{"title":"Original practice passage","paragraphs":["The report's tone is “cautious”: it describes the preliminary result as promising but emphasizes the need for a larger sample."]}},{"id":"RWM2HQ15","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Sentence boundaries","difficulty":"hard","prompt":"The river rose rapidly overnight ___ by morning, several roads were closed.","options":["overnight, by","overnight; by","overnight by","overnight: by"],"answer":"B","explanation":"Two independent clauses are joined with a semicolon.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The river rose rapidly overnight ___ by morning, several roads were closed."]}},{"id":"RWM2HQ16","section":"Reading and Writing","domain":"Information and Ideas","skill":"Inference","difficulty":"hard","prompt":"Which statement is most appropriate?","options":["The timing of feedback may be associated with revision, but motivation could also matter.","Fast feedback proves that every student revises more.","Motivation had no effect on the study.","Late feedback causes students to stop writing."],"answer":"A","explanation":"The uncontrolled motivation variable limits a causal conclusion.","source":{"title":"Original practice passage","paragraphs":["Students who received feedback within 24 hours revised their essays more often than students who received feedback after one week. The study did not control for how motivated the students were."]}},{"id":"RWM2HQ17","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice most effectively highlights the catalog's lasting contribution?","options":["Chen's multi-observatory catalog of 1,800 variable stars later helped researchers identify unusual stellar behavior.","Chen worked with three observatories while studying stars.","Variable stars can change brightness over time.","Researchers often compare observations from different observatories."],"answer":"A","explanation":"It connects the scale and method of the catalog to its later use.","source":{"title":"Original practice passage","paragraphs":["Notes: astronomer Lina Chen cataloged 1,800 variable stars; her catalog included measurements from three observatories; later researchers used it to identify unusual stellar behavior."]}},{"id":"RWM2HQ18","section":"Reading and Writing","domain":"Craft and Structure","skill":"Text structure and purpose","difficulty":"hard","prompt":"What is the primary function of the measurements?","options":["To challenge the initial explanation with direct evidence","To define sediment","To describe a second lake","To explain how water is filtered"],"answer":"A","explanation":"The measurements contradict the opening explanation.","source":{"title":"Original practice passage","paragraphs":["The passage begins with a common explanation for why a lake became clearer, then introduces sediment measurements that contradict that explanation."]}},{"id":"RWM2HQ19","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Punctuation","difficulty":"hard","prompt":"The researchers tracked three variables ___ temperature, humidity, and soil moisture ___ at hourly intervals.","options":["variables: temperature, humidity, and soil moisture","variables; temperature, humidity, and soil moisture","variables, temperature, humidity, and soil moisture","variables temperature, humidity, and soil moisture"],"answer":"A","explanation":"A colon appropriately introduces the list.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The researchers tracked three variables ___ temperature, humidity, and soil moisture ___ at hourly intervals."]}},{"id":"RWM2HQ20","section":"Reading and Writing","domain":"Information and Ideas","skill":"Quantitative evidence","difficulty":"hard","prompt":"What percentage of residents were undecided?","options":["15%","20%","25%","35%"],"answer":"A","explanation":"There are 36 undecided residents; 36 ÷ 240 = 15%.","source":{"title":"Original practice passage","paragraphs":["A survey of 240 residents found that 156 supported the proposed transit line, 48 opposed it, and the remainder were undecided."]}},{"id":"RWM2HQ21","section":"Reading and Writing","domain":"Craft and Structure","skill":"Cross-text connections","difficulty":"hard","prompt":"Which statement best synthesizes the texts?","options":["Community science can expand data collection, especially when experts provide consistent methods.","Community science should replace professional researchers.","Experts should collect all data themselves.","Volunteer observations are always unreliable."],"answer":"A","explanation":"Both texts support participation while emphasizing the importance of sound methods.","source":{"title":"Original practice passage","paragraphs":["Text 1 presents community science as a way to expand data collection. Text 2 argues that volunteer observations are most valuable when experts establish clear protocols."]}},{"id":"RWM2HQ22","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","prompt":"The historical record is incomplete. ___, letters preserved in family archives offer details unavailable in official reports.","options":["Nevertheless","Consequently","Likewise","For example"],"answer":"A","explanation":"Despite the incomplete record, the letters provide useful details.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The historical record is incomplete. ___, letters preserved in family archives offer details unavailable in official reports."]}},{"id":"RWM2HQ23","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Pronoun reference","difficulty":"hard","prompt":"The committee reviewed the proposal and its budget before publishing ___ recommendations.","options":["their","its","it's","they're"],"answer":"B","explanation":"“Committee” is singular in formal agreement here, so “its” refers to the committee.","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The committee reviewed the proposal and its budget before publishing ___ recommendations."]}},{"id":"RWM2HQ24","section":"Reading and Writing","domain":"Information and Ideas","skill":"Central ideas","difficulty":"hard","prompt":"Which choice best describes the finding?","options":["The material's strength depended on both drying and subsequent heating.","Drying always weakened the material.","Heating had no measurable effect.","The researchers confirmed their original expectation."],"answer":"A","explanation":"The strongest result occurred only when heating followed drying.","source":{"title":"Original practice passage","paragraphs":["At first, the researchers expected the material to become stronger when dried. Instead, strength increased only after a brief heating stage followed the drying process."]}},{"id":"RWM2HQ25","section":"Reading and Writing","domain":"Craft and Structure","skill":"Words in context","difficulty":"hard","prompt":"As used in the text, “anomaly” most nearly means","options":["unexpected observation","confirmed prediction","routine measurement","published conclusion"],"answer":"A","explanation":"An anomaly is an observation that does not fit the expected pattern.","source":{"title":"Original practice passage","paragraphs":["The biologist treats the apparent anomaly as “informative,” since it exposes a limitation in the model rather than simply representing error."]}},{"id":"RWM2HQ26","section":"Reading and Writing","domain":"Expression of Ideas","skill":"Rhetorical synthesis","difficulty":"hard","prompt":"Which choice best explains how the theater restored the marquee?","options":["Using archival photographs, the theater recreated the marquee's original 1920s color scheme.","The theater reopened its doors after a renovation.","Archival photographs can preserve historical details.","The marquee is one of the building's most visible features."],"answer":"A","explanation":"It incorporates the method and result from the notes.","source":{"title":"Original practice passage","paragraphs":["Notes: a theater restored its 1920s marquee; the restoration used archival photographs; the marquee now matches the building's original color scheme."]}},{"id":"RWM2HQ27","section":"Reading and Writing","domain":"Standard English Conventions","skill":"Verb form","difficulty":"hard","prompt":"The editor requested that every quotation ___ checked against the original recording.","options":["is","be","was","will be"],"answer":"B","explanation":"The mandative subjunctive takes “be checked.”","source":{"title":"Original practice passage","paragraphs":["The passage presents a situation that illustrates the relationship described in the question: The editor requested that every quotation ___ checked against the original recording."]}}]},
"math1":[{"id":"MM1Q1","section":"Math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","prompt":"A researcher has recorded 5 more samples than twice the number of samples in an earlier trial. The researcher recorded 23 samples in the new trial. How many samples were recorded in the earlier trial?","type":"spr","options":[],"answer":"9","explanation":"Let x be the earlier number. Then 2x+5=23, so x=9."},{"id":"MM1Q2","section":"Math","domain":"Algebra","skill":"Linear equations in two variables","difficulty":"easy","prompt":"A line has equation 3x+2y=14. Which equation gives y in terms of x?","type":"mcq","options":["y=7+1.5x","y=7−3x","y=7−1.5x","y=14−1.5x"],"answer":"C","explanation":"Solving for y gives 2y=14−3x, so y=7−1.5x."},{"id":"MM1Q3","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"easy","prompt":"A delivery service charges a fixed fee plus the same amount for each mile. A 4-mile delivery costs $14 and a 10-mile delivery costs $26. What is the charge per mile?","type":"mcq","options":["$1","$2","$3","$4"],"answer":"B","explanation":"The cost increases by 12 dollars over 6 miles, so the rate is 12/6=2 dollars per mile."},{"id":"MM1Q4","section":"Math","domain":"Algebra","skill":"Systems of equations","difficulty":"easy","prompt":"The system 2x+y=13 and x−y=2 has solution (x,y). What is x?","type":"mcq","options":["3","5","7","11"],"answer":"B","explanation":"Adding the equations gives 3x=15, so x=5."},{"id":"MM1Q5","section":"Math","domain":"Algebra","skill":"Linear inequalities","difficulty":"easy","prompt":"Which inequality represents all values of x for which a number increased by 6 is at most 18?","type":"mcq","options":["x≤12","x≥12","x<24","x>24"],"answer":"A","explanation":"The statement translates directly to x+6≤18, so x≤12."},{"id":"MM1Q6","section":"Math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","prompt":"A tank contains 160 liters of water. It is drained at 6 liters per minute. Which equation gives the amount A remaining after t minutes?","type":"mcq","options":["A=6t−160","A=160+6t","A=154t","A=160−6t"],"answer":"D","explanation":"The initial amount is 160 and the amount decreases by 6 each minute."},{"id":"MM1Q7","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"easy","prompt":"A linear function f satisfies f(2)=11 and f(6)=27. What is f(10)?","type":"mcq","options":["31","39","43","47"],"answer":"C","explanation":"The slope is (27−11)/(6−2)=4. Four more units of x add 16, so f(10)=43."},{"id":"MM1Q8","section":"Math","domain":"Advanced Math","skill":"Quadratic equations","difficulty":"easy","prompt":"If x²−9x+20=0, what is the greater solution?","type":"mcq","options":["2","3","4","5"],"answer":"D","explanation":"The equation factors as (x−4)(x−5)=0, so the greater solution is 5."},{"id":"MM1Q9","section":"Math","domain":"Advanced Math","skill":"Quadratic functions","difficulty":"easy","prompt":"The function g(x)=x²−8x+19 is written in vertex form as (x−4)²+k. What is k?","type":"mcq","options":["3","4","11","19"],"answer":"A","explanation":"x²−8x+19=(x−4)²+3, so k=3."},{"id":"MM1Q10","section":"Math","domain":"Advanced Math","skill":"Exponential equations","difficulty":"easy","prompt":"If 2^(x+1)=64, what is x?","type":"spr","options":[],"answer":"5","explanation":"Since 64=2^6, x+1=6 and x=5."},{"id":"MM1Q11","section":"Math","domain":"Advanced Math","skill":"Rational equations","difficulty":"medium","prompt":"For x≠2, (x+4)/(x−2)=2. What is x?","type":"mcq","options":["8","6","4","2"],"answer":"A","explanation":"Multiplying gives x+4=2x−4, so x=8."},{"id":"MM1Q12","section":"Math","domain":"Advanced Math","skill":"Equivalent expressions","difficulty":"medium","prompt":"Which expression is equivalent to (x+3)²−x²?","type":"mcq","options":["3x+9","6x+3","6x+9","x²+9"],"answer":"C","explanation":"Expanding gives x²+6x+9−x²=6x+9."},{"id":"MM1Q13","section":"Math","domain":"Advanced Math","skill":"Systems of equations in two variables","difficulty":"medium","prompt":"The equations x+y=9 and xy=18 have two solutions. What is the smaller value of x?","type":"mcq","options":["1","3","6","18"],"answer":"B","explanation":"The numbers are 3 and 6 because they sum to 9 and multiply to 18."},{"id":"MM1Q14","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Percentages","difficulty":"easy","prompt":"A laptop priced at $800 is discounted by 15%. What is the sale price?","type":"mcq","options":["$620","$660","$680","$700"],"answer":"C","explanation":"A 15% discount is 120 dollars, so the sale price is 680 dollars."},{"id":"MM1Q15","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Ratios, rates, proportional relationships, and units","difficulty":"easy","prompt":"A machine packages 84 boxes in 7 minutes at a constant rate. At this rate, how many boxes will it package in 15 minutes?","type":"mcq","options":["180","192","210","240"],"answer":"A","explanation":"The rate is 12 boxes per minute, so 12×15=180."},{"id":"MM1Q16","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"One-variable data: measures of center","difficulty":"medium","prompt":"Five test scores have a mean of 72. If one score of 64 is removed, what is the mean of the remaining four scores?","type":"mcq","options":["68","70","72","74"],"answer":"D","explanation":"The original total is 5×72=360. Removing 64 leaves 296, and 296/4=74."},{"id":"MM1Q17","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"medium","prompt":"A box contains 5 black pens, 3 blue pens, and 2 red pens. If one pen is selected at random, what is the probability it is not blue?","type":"mcq","options":["3/10","1/2","7/10","4/5"],"answer":"C","explanation":"There are 7 non-blue pens out of 10 total, so the probability is 7/10."},{"id":"MM1Q18","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Two-variable data: models","difficulty":"medium","prompt":"A model for the number of plants sold, y, based on advertising visits, x, is y=18+4x. According to the model, how many additional plants are sold for each additional visit?","type":"mcq","options":["4","18","22","72"],"answer":"B","explanation":"The coefficient of x is 4, which is the predicted change in y for one additional visit."},{"id":"MM1Q19","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and volume formulas","difficulty":"medium","prompt":"A right triangle has legs of lengths 9 and 12. What is the length of the hypotenuse?","type":"mcq","options":["13","14","15","21"],"answer":"C","explanation":"By the Pythagorean theorem, the hypotenuse is √(81+144)=√225=15."},{"id":"MM1Q20","section":"Math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"hard","prompt":"A circle has radius 8. An arc subtends a central angle of 90°. What is the length of the arc, in terms of π?","type":"mcq","options":["2π","4π","8π","16π"],"answer":"B","explanation":"A 90° arc is one-fourth of the circumference, so the length is 4π."},{"id":"MM1Q21","section":"Math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"hard","prompt":"In a right triangle, sin θ=3/5 and the hypotenuse is 20. What is the length of the side opposite θ?","type":"mcq","options":["8","10","15","12"],"answer":"D","explanation":"Sine is opposite/hypotenuse, so opposite=(3/5)×20=12."},{"id":"MM1Q22","section":"Math","domain":"Geometry and Trigonometry","skill":"Coordinate geometry","difficulty":"hard","prompt":"The vertices of a rectangle are (1,2), (7,2), (7,5), and (1,5). What is the area of the rectangle?","type":"mcq","options":["18","20","24","30"],"answer":"A","explanation":"The side lengths are 6 and 3, so the area is 18."}],"math2":{"easy":[{"id":"MM2EQ1","section":"Math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","prompt":"If 7x−12=30, what is x?","type":"spr","options":[],"answer":"6","explanation":"Adding 12 gives 7x=42, so x=6."},{"id":"MM2EQ2","section":"Math","domain":"Algebra","skill":"Systems of equations","difficulty":"easy","prompt":"The system x+y=12 and x−y=4 has solution (x,y). What is y?","type":"mcq","options":["2","4","8","16"],"answer":"B","explanation":"Adding gives 2x=16, so x=8 and y=4."},{"id":"MM2EQ3","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"easy","prompt":"A taxi fare is modeled by C=5+2.25m, where m is the number of miles. What does 2.25 represent?","type":"mcq","options":["The starting fare","The total fare","The number of miles","The charge per mile"],"answer":"D","explanation":"The coefficient of m is the rate charged for each mile."},{"id":"MM2EQ4","section":"Math","domain":"Algebra","skill":"Linear inequalities","difficulty":"easy","prompt":"Which value of x satisfies 4x−3>9?","type":"mcq","options":["2","3","5","−2"],"answer":"C","explanation":"The inequality gives x>3. Of the choices, 5 satisfies it."},{"id":"MM2EQ5","section":"Math","domain":"Algebra","skill":"Linear equations in context","difficulty":"easy","prompt":"A school buys notebooks at $4 each and pays a one-time $12 delivery fee. The total is $48. How many notebooks were purchased?","type":"mcq","options":["6","9","12","15"],"answer":"B","explanation":"4n+12=48, so n=9."},{"id":"MM2EQ6","section":"Math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"medium","prompt":"For what value of x are 3(x−2) and 2x+5 equal?","type":"mcq","options":["11","7","5","−1"],"answer":"A","explanation":"Set 3x−6=2x+5, giving x=11."},{"id":"MM2EQ7","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"medium","prompt":"A line passes through (2,5) and (8,20). What is its y-intercept?","type":"mcq","options":["−5","−1","0","5"],"answer":"C","explanation":"The slope is 2.5. Using (2,5), the y-intercept is 0."},{"id":"MM2EQ8","section":"Math","domain":"Advanced Math","skill":"Quadratic equations","difficulty":"easy","prompt":"Which value is a solution to x²−7x+12=0?","type":"mcq","options":["2","3","5","6"],"answer":"B","explanation":"The polynomial factors as (x−3)(x−4), so 3 is a solution."},{"id":"MM2EQ9","section":"Math","domain":"Advanced Math","skill":"Exponential expressions","difficulty":"easy","prompt":"What is the value of 3²·3³?","type":"mcq","options":["81","108","162","243"],"answer":"D","explanation":"Add exponents: 3^5=243."},{"id":"MM2EQ10","section":"Math","domain":"Advanced Math","skill":"Functions","difficulty":"medium","prompt":"Let f(x)=x²−2. What is f(5)+f(−3)?","type":"mcq","options":["30","28","26","20"],"answer":"A","explanation":"f(5)=23 and f(−3)=7, giving 30."},{"id":"MM2EQ11","section":"Math","domain":"Advanced Math","skill":"Equivalent expressions","difficulty":"medium","prompt":"Which expression is equivalent to (2x−3)(x+5)?","type":"mcq","options":["2x²+13x−15","2x²−7x−15","2x²+7x−15","2x²+7x+15"],"answer":"C","explanation":"Multiplying gives 2x²+7x−15."},{"id":"MM2EQ12","section":"Math","domain":"Advanced Math","skill":"Radical equations","difficulty":"medium","prompt":"If √(x+4)=6, what is x?","type":"mcq","options":["28","32","34","40"],"answer":"B","explanation":"Squaring gives x+4=36, so x=32."},{"id":"MM2EQ13","section":"Math","domain":"Advanced Math","skill":"Nonlinear equations","difficulty":"medium","prompt":"The equation x²=5x+14 has two solutions. What is the greater solution?","type":"mcq","options":["−7","−2","2","7"],"answer":"D","explanation":"Rearrange to x²−5x−14=0=(x−7)(x+2). The greater solution is 7."},{"id":"MM2EQ14","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Percentages","difficulty":"easy","prompt":"A population of 2,400 increases by 10%. What is the new population?","type":"mcq","options":["2,420","2,500","2,640","2,880"],"answer":"C","explanation":"A 10% increase adds 240, giving 2,640."},{"id":"MM2EQ15","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"One-variable data: measures of center","difficulty":"easy","prompt":"The data set 4, 7, 9, 9, 11 has median 9. If 15 is added to the set, what is the new median?","type":"mcq","options":["7","9","10","11"],"answer":"B","explanation":"The ordered data are 4,7,9,9,11,15, so the middle pair is 9 and 9."},{"id":"MM2EQ16","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Ratios, rates, proportional relationships, and units","difficulty":"medium","prompt":"A runner completes 5 kilometers in 24 minutes at a constant pace. Approximately how many minutes per kilometer is the pace?","type":"mcq","options":["4.8","5.2","19","29"],"answer":"A","explanation":"24/5=4.8 minutes per kilometer."},{"id":"MM2EQ17","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"medium","prompt":"A class has 12 juniors and 18 seniors. Four juniors and 6 seniors are in the science club. If a student in the science club is chosen at random, what is the probability the student is a junior?","type":"mcq","options":["1/5","1/3","2/5","1/2"],"answer":"C","explanation":"There are 10 science-club students, 4 of whom are juniors, so the probability is 2/5."},{"id":"MM2EQ18","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Two-variable data: models","difficulty":"medium","prompt":"A scatterplot is modeled by y=3x+7. If x increases by 4, what is the predicted increase in y?","type":"mcq","options":["4","7","10","12"],"answer":"D","explanation":"The slope is 3, so an increase of 4 in x predicts an increase of 12 in y."},{"id":"MM2EQ19","section":"Math","domain":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"easy","prompt":"Two angles of a triangle measure 47° and 68°. What is the measure of the third angle?","type":"mcq","options":["55°","60°","65°","75°"],"answer":"C","explanation":"Triangle angles sum to 180°, so the third angle is 65°."},{"id":"MM2EQ20","section":"Math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"medium","prompt":"A circle has diameter 18. What is its area in terms of π?","type":"mcq","options":["81π","36π","18π","9π"],"answer":"A","explanation":"The radius is 9, so the area is 81π."},{"id":"MM2EQ21","section":"Math","domain":"Geometry and Trigonometry","skill":"Similarity","difficulty":"hard","prompt":"Two similar triangles have corresponding side lengths in the ratio 2:3. If the smaller triangle has area 20, what is the area of the larger triangle?","type":"mcq","options":["30","36","40","45"],"answer":"D","explanation":"Areas scale by (3/2)², so the larger area is 45."},{"id":"MM2EQ22","section":"Math","domain":"Geometry and Trigonometry","skill":"Coordinate geometry","difficulty":"hard","prompt":"A line segment has endpoints (−2,1) and (4,9). What is its length?","type":"mcq","options":["8","10","12","14"],"answer":"B","explanation":"The horizontal and vertical changes are 6 and 8, so the distance is 10."}],"hard":[{"id":"MM2HQ1","section":"Math","domain":"Algebra","skill":"Systems of equations","difficulty":"hard","prompt":"A theater sells adult tickets for $15 and student tickets for $9. One performance sold 128 tickets for $1,602. How many adult tickets were sold?","type":"mcq","options":["68","72","75","80"],"answer":"C","explanation":"Let a be adult tickets. Then a+s=128 and 15a+9s=1602. Substitution gives 6a=450, so a=75."},{"id":"MM2HQ2","section":"Math","domain":"Algebra","skill":"Linear functions in context","difficulty":"hard","prompt":"A water tank is filled at a constant rate. After 8 minutes it contains 186 liters, and after 20 minutes it contains 402 liters. What was the amount of water in the tank at time 0?","type":"mcq","options":["42","48","60","96"],"answer":"A","explanation":"The rate is 18 liters per minute. Subtracting 8·18 from 186 gives 42 liters."},{"id":"MM2HQ3","section":"Math","domain":"Algebra","skill":"Absolute-value inequalities","difficulty":"hard","prompt":"What is the greatest integer x that satisfies |2x−7|≤11?","type":"mcq","options":["7","8","9","10"],"answer":"C","explanation":"The inequality gives −2≤x≤9, so the greatest integer is 9."},{"id":"MM2HQ4","section":"Math","domain":"Algebra","skill":"Linear equations with parameters","difficulty":"hard","prompt":"For what value of k does the equation 4x+k=3x+17 have solution x=5?","type":"mcq","options":["7","12","15","22"],"answer":"B","explanation":"Substitute x=5: 20+k=32, so k=12."},{"id":"MM2HQ5","section":"Math","domain":"Algebra","skill":"Systems of equations","difficulty":"hard","prompt":"The system 3x+2y=22 and x−2y=2 has solution (x,y). What is x+y?","type":"mcq","options":["6","7","8","10"],"answer":"C","explanation":"Adding gives 4x=24, so x=6; then y=2 and x+y=8."},{"id":"MM2HQ6","section":"Math","domain":"Algebra","skill":"Linear inequalities in context","difficulty":"hard","prompt":"A supplier charges $240 plus $18 for each case. A school can spend at most $600. What is the greatest number of complete cases the school can buy?","type":"mcq","options":["20","21","22","24"],"answer":"A","explanation":"240+18n≤600, so n≤20."},{"id":"MM2HQ7","section":"Math","domain":"Algebra","skill":"Linear functions","difficulty":"hard","prompt":"A line has x-intercept 6 and y-intercept −4. Which equation represents the line?","type":"mcq","options":["y=2x−4","y=(2/3)x−4","y=−(2/3)x+4","y=3x−4"],"answer":"B","explanation":"The slope is (0−(−4))/(6−0)=2/3 and the y-intercept is −4."},{"id":"MM2HQ8","section":"Math","domain":"Advanced Math","skill":"Quadratic functions with parameters","difficulty":"hard","prompt":"The quadratic x²−(k+2)x+2k=0 has roots that differ by 4. What is the positive value of k?","type":"mcq","options":["2","4","6","8"],"answer":"C","explanation":"The quadratic factors as (x−2)(x−k). The roots differ by 4, so k=6."},{"id":"MM2HQ9","section":"Math","domain":"Advanced Math","skill":"Exponential equations","difficulty":"hard","prompt":"If 3^(2x−1)=27^(x−2), what is x?","type":"mcq","options":["1","3","4","5"],"answer":"D","explanation":"Since 27=3³, 2x−1=3x−6, so x=5."},{"id":"MM2HQ10","section":"Math","domain":"Advanced Math","skill":"Rational equations","difficulty":"hard","prompt":"For x≠3, (x+1)/(x−3)=2. What is x?","type":"mcq","options":["7","5","4","3"],"answer":"A","explanation":"x+1=2x−6, so x=7."},{"id":"MM2HQ11","section":"Math","domain":"Advanced Math","skill":"Polynomial factorization","difficulty":"hard","prompt":"The polynomial x³−4x²−x+4 can be factored as (x−4)(x²−1). Which of the following is the complete set of real solutions to x³−4x²−x+4=0?","type":"mcq","options":["−4, 1, 4","−1, 1, 4","−1, 4","1, 4"],"answer":"B","explanation":"The factors are (x−4)(x−1)(x+1), so the solutions are −1, 1, and 4."},{"id":"MM2HQ12","section":"Math","domain":"Advanced Math","skill":"Radical equations","difficulty":"hard","prompt":"For x≥0, √(x+9)=x−3. What is the solution?","type":"mcq","options":["0","3","7","9"],"answer":"C","explanation":"Squaring gives x(x−7)=0; x=0 fails the original equation, leaving x=7."},{"id":"MM2HQ13","section":"Math","domain":"Advanced Math","skill":"Function composition","difficulty":"hard","prompt":"Let f(x)=x²−1 and g(x)=2x+3. What is f(g(2))?","type":"mcq","options":["48","49","50","51"],"answer":"A","explanation":"g(2)=7, and f(7)=48."},{"id":"MM2HQ14","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Percent change","difficulty":"hard","prompt":"A quantity is increased by 25% and then decreased by 20%. What is the overall percent change?","type":"mcq","options":["5% increase","No change","5% decrease","20% decrease"],"answer":"B","explanation":"The combined multiplier is 1.25×0.80=1, so there is no overall change."},{"id":"MM2HQ15","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"hard","prompt":"A bag contains 7 red marbles and 5 blue marbles. Two marbles are selected without replacement. What is the probability that both are red?","type":"mcq","options":["7/12","5/11","1/2","7/22"],"answer":"D","explanation":"The probability is (7/12)(6/11)=7/22."},{"id":"MM2HQ16","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Inference from sample statistics","difficulty":"hard","prompt":"A survey of 500 randomly selected voters finds that 52% support a proposal, with a margin of error of 4 percentage points. Which interval represents the estimate plus or minus the margin of error?","type":"mcq","options":["48% to 56%","50% to 54%","52% to 56%","48% to 52%"],"answer":"A","explanation":"52%−4%=48% and 52%+4%=56%."},{"id":"MM2HQ17","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"One-variable data: spread","difficulty":"hard","prompt":"A data set has standard deviation 6. Every value is multiplied by 1.5 and then increased by 4. What is the new standard deviation?","type":"mcq","options":["6","7.5","9","13"],"answer":"C","explanation":"Adding 4 does not change spread; multiplying by 1.5 gives 9."},{"id":"MM2HQ18","section":"Math","domain":"Problem-Solving and Data Analysis","skill":"Two-way tables","difficulty":"hard","prompt":"In a survey of 240 students, 90 are in band. Of the students in band, 54 also play a sport. What percentage of band students also play a sport?","type":"mcq","options":["22.5%","60%","64%","75%"],"answer":"B","explanation":"54/90=0.60, or 60%."},{"id":"MM2HQ19","section":"Math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"hard","prompt":"A circle has center (3,−2) and radius 5. Which equation represents the circle?","type":"mcq","options":["(x+3)²+(y−2)²=25","(x−3)²+(y−2)²=25","(x+3)²+(y+2)²=5","(x−3)²+(y+2)²=25"],"answer":"D","explanation":"Use (x−h)²+(y−k)²=r²."},{"id":"MM2HQ20","section":"Math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"hard","prompt":"In a right triangle, tan θ=5/12 and the side adjacent to θ has length 24. What is the side opposite θ?","type":"mcq","options":["10","12","20","24"],"answer":"A","explanation":"tan θ=opposite/adjacent, so opposite=(5/12)×24=10."},{"id":"MM2HQ21","section":"Math","domain":"Geometry and Trigonometry","skill":"Area and similarity","difficulty":"hard","prompt":"Two similar rectangles have side-length ratio 3:5. If the smaller rectangle has area 54 square units, what is the area of the larger rectangle?","type":"mcq","options":["90","120","150","180"],"answer":"C","explanation":"Areas scale by (5/3)², so 54×25/9=150."},{"id":"MM2HQ22","section":"Math","domain":"Geometry and Trigonometry","skill":"Volume","difficulty":"hard","prompt":"A cylinder has radius 4 and height 9. A cone has the same radius and height 9. What is the sum of their volumes, in terms of π?","type":"mcq","options":["144π","192π","288π","432π"],"answer":"B","explanation":"The cylinder volume is 144π and the cone volume is 48π, for a total of 192π."}]}};window.SAT_QUESTIONS.rw2.easy=window.SAT_QUESTIONS.rw1.map((q,i)=>({...q,id:`RWM2EQ${i+1}`}));window.SAT_QUESTIONS.math2.easy=window.SAT_QUESTIONS.math2.easy.map(q=>q);